-- Preserve only currently valid cached decisions; never repair renewal/task states.
UPDATE system.manual_product_todos m JOIN (SELECT q.source,q.id,SHA2(CONCAT(q.source,':',q.id,':',q.customer_id,':',CASE WHEN q.source='instance' THEN (SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM instance.instance_events WHERE instance_id=CAST(q.id AS UNSIGNED) AND status=3) ELSE '' END,':',CASE WHEN q.source='instance' THEN (SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM instance.instance_renewals WHERE instance_id=CAST(q.id AS UNSIGNED) AND state IN ('uncertain','failed','verifying')) ELSE '' END,':',CASE WHEN q.source='instance' THEN (SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM instance.instance_upgrades WHERE instance_id=CAST(q.id AS UNSIGNED) AND state IN ('creating','paying','uncertain','verifying')) ELSE '' END,':',(SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM `order`.delivery_units WHERE ((q.source='instance' AND instance_id=CAST(q.id AS UNSIGNED)) OR (q.source='order' AND order_item_id=CAST(q.id AS UNSIGNED))) AND status IN ('unknown','failed')),':',CASE WHEN q.source='order' THEN (SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM `order`.order_items WHERE id=CAST(q.id AS UNSIGNED)) ELSE '' END,':',(SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM system.durable_tasks WHERE kind='post_payment' AND status IN ('unknown','failed') AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.customerId'))=q.customer_id AND ((JSON_UNQUOTE(JSON_EXTRACT(payload,'$.businessType'))='order' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.businessId'))=q.order_id) OR (JSON_UNQUOTE(JSON_EXTRACT(payload,'$.businessType'))='order_unit' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.businessId')) IN (SELECT CAST(d.id AS CHAR) FROM `order`.delivery_units d WHERE (q.source='instance' AND d.instance_id=CAST(q.id AS UNSIGNED)) OR (q.source='order' AND d.order_item_id=CAST(q.id AS UNSIGNED))))))),256) old_revision,SHA2(CONCAT(q.source,':',q.id,':',q.customer_id,':',CASE WHEN q.source='instance' THEN (SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM instance.instance_events WHERE instance_id=CAST(q.id AS UNSIGNED) AND status=3 AND event_type IN ('create','suspend','terminate','destroy','renew','sync_due_time','unsuspend')) ELSE '' END,':',CASE WHEN q.source='instance' THEN (SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM instance.instance_renewals WHERE instance_id=CAST(q.id AS UNSIGNED) AND state IN ('uncertain','failed','verifying')) ELSE '' END,':',CASE WHEN q.source='instance' THEN (SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM instance.instance_upgrades WHERE instance_id=CAST(q.id AS UNSIGNED) AND state IN ('creating','paying','uncertain','verifying')) ELSE '' END,':',(SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM `order`.delivery_units WHERE ((q.source='instance' AND instance_id=CAST(q.id AS UNSIGNED)) OR (q.source='order' AND order_item_id=CAST(q.id AS UNSIGNED))) AND status IN ('unknown','failed')),':',CASE WHEN q.source='order' THEN (SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM `order`.order_items WHERE id=CAST(q.id AS UNSIGNED)) ELSE '' END,':',(SELECT CONCAT(COUNT(*),':',COALESCE(DATE_FORMAT(MAX(updated_at),'%Y-%m-%d %H:%i:%s.%f'),'')) FROM system.durable_tasks WHERE kind='post_payment' AND status IN ('unknown','failed') AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.customerId'))=q.customer_id AND ((JSON_UNQUOTE(JSON_EXTRACT(payload,'$.businessType'))='order' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.businessId'))=q.order_id) OR (JSON_UNQUOTE(JSON_EXTRACT(payload,'$.businessType'))='order_unit' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.businessId')) IN (SELECT CAST(d.id AS CHAR) FROM `order`.delivery_units d WHERE (q.source='instance' AND d.instance_id=CAST(q.id AS UNSIGNED)) OR (q.source='order' AND d.order_item_id=CAST(q.id AS UNSIGNED))))))),256) new_revision FROM (SELECT 'instance' source,CAST(id AS CHAR) id,CAST(customer_id AS CHAR) customer_id,CAST(order_id AS CHAR) order_id FROM instance.instances UNION ALL SELECT 'order',CAST(oi.id AS CHAR),CAST(o.customer_id AS CHAR),CAST(o.id AS CHAR) FROM `order`.order_items oi JOIN `order`.orders o ON o.id=oi.order_id) q) v ON v.source=m.source AND CAST(v.id AS UNSIGNED)=m.object_id SET m.revision=v.new_revision WHERE m.state IN ('normal','processed') AND m.revision=v.old_revision;
